'use client';

import type { ImageLoaderProps } from 'next/image';

import variants from './imageVariants.json';

const VARIANTS: Record<string, number[]> = variants;

// GitHub Pages has no image optimizer: next/image builds its srcset from the
// copies pre-generated by scripts/generate-image-variants.mjs, and falls back
// to the original file (static imports, images without copies, widths bigger
// than every copy).
export default function imageLoader({ src, width }: ImageLoaderProps) {
  const variantWidth = VARIANTS[src]?.find((candidate) => candidate >= width);
  if (!variantWidth) return src;
  return `/img-variants${src.replace(/\.webp$/, `-${variantWidth}w.webp`)}`;
}
